// ───────────────────────────── short payments (v18.7, 23 Oct 2026) ─────────────────────────────
// The customer paid less than the bill. The bill stays as it is (GST invoice); the shortfall is recorded with a reason,
// and the bill's Cash / UPI / Card column is reduced to what was actually received, so the day's cash tallies.
const SH_TAB = 'Short Payments', SH_H = ['Bill no.', 'Bill date', 'Location', 'Event', 'Bill total ₹', 'Received ₹', 'Short ₹', 'Short in', 'Reason', 'Note',
  'Recorded by', 'Recorded at', 'Status'];
const SHORT_REASONS = ['Customer bargained / paid less', 'Change not available (rounded down)', 'Customer short of money – will pay later', 'Staff mistake', 'Other'];
function shRows_() { const sh = btab2_(SH_TAB, SH_H), n = sh.getLastRow() - 1; return { sh: sh, rows: n < 1 ? [] : sh.getRange(2, 1, n, SH_H.length).getValues() }; }
function btab2_(name, head) {
  const ss = billBook_(); let sh = ss.getSheetByName(name);
  if (!sh) { sh = ss.insertSheet(name); sh.getRange(1, 1, 1, head.length).setValues([head]).setFontWeight('bold').setBackground('#1F2A44').setFontColor('#F7F1DE'); sh.setFrozenRows(1); sh.getRange('A:A').setNumberFormat('@'); }
  return sh;
}
function billBook_() { return book_(); }
function shortMap_() {
  const o = {};
  shRows_().rows.forEach(r => { if (s_(r[12]) === 'Active') o[s_(r[0])] = { short: n_(r[6]), received: n_(r[5]), mode: s_(r[7]), reason: s_(r[8]), note: s_(r[9]), by: s_(r[10]), at: iso_(r[11]) }; });
  return o;
}
function shortsIn_(from, to, loc, scope, user) {
  return shRows_().rows.filter(r => s_(r[12]) === 'Active' && ymd_(r[1]) >= from && ymd_(r[1]) <= to && (!loc || loc === 'All' || s_(r[2]) === loc) && inScope_(scope, s_(r[2])))
    .map(r => ({ no: s_(r[0]), date: ymd_(r[1]), loc: s_(r[2]), event: s_(r[3]), total: n_(r[4]), received: n_(r[5]), short: n_(r[6]), mode: s_(r[7]), reason: s_(r[8]), note: s_(r[9]), by: s_(r[10]) }));
}
/** Sets the bill's payment columns to the full amounts minus the active short (if any). */
function applyShortToBill_(row, r, b, sx) {
  const full = b.payFull || b.pay; b.payFull = full;
  const p = { cash: n_(full.cash), upi: n_(full.upi), card: n_(full.card), other: n_(full.other) };
  if (sx) { const k = sx.mode.toLowerCase(); p[k] = round2_(Math.max(0, p[k] - sx.short)); }
  b.pay = Object.assign({ mode: full.mode }, p); b.short = sx || null;
  r[BC['Cash ₹']] = p.cash; r[BC['UPI ₹']] = p.upi; r[BC['Card ₹']] = p.card; r[BC['Other ₹']] = p.other; r[BC['Bill data']] = JSON.stringify(b);
  btab_('bills').getRange(row, 1, 1, r.length).setValues([r]);
}
function shortGuard_(r, user, fresh) {
  if (s_(r[BC['Status']]) === 'Cancelled') throw new Error('This bill is cancelled.');
  if (!billInScope_({ loc: s_(r[BC['Location']]), by: s_(r[BC['Billed by']]) }, user)) throw new Error('You can only do this for bills of your own store.');
  const days = (new Date(ymd_(new Date()) + 'T00:00:00') - new Date(ymd_(r[BC['Date']]) + 'T00:00:00')) / 864e5;
  if (!fresh && !can_(user, 'cancelBill') && days > 1) throw new Error('Short payments can be recorded on the day of the bill (or the next day). Ask the owner for older bills.');
}
/** d = {no, received, mode:'Cash'|'UPI'|'Card', reason, note} */
function recordShort_(d, user, fresh) {
  const reason = SHORT_REASONS.indexOf(d.reason) >= 0 ? d.reason : '';
  if (!reason) throw new Error('Pick the reason for the short payment.');
  if (reason === 'Other' && !txt_(d.note, 200)) throw new Error('Type a note for "Other".');
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    const row = findBillRow_(d.no); if (row < 0) throw new Error('Bill not found.');
    const r = btab_('bills').getRange(row, 1, 1, BH.bills.length).getValues()[0];
    shortGuard_(r, user, fresh);
    const b = JSON.parse(s_(r[BC['Bill data']])), full = b.payFull || b.pay, total = n_(r[BC['Total ₹']]);
    const received = round2_(n_(d.received));
    if (!(received >= 0) || received >= total) throw new Error('Amount received must be less than the bill (₹' + total + ').');
    const mode = full.mode === 'Split' ? (['Cash', 'UPI', 'Card'].indexOf(d.mode) >= 0 ? d.mode : '') : full.mode;
    if (!mode) throw new Error('Pick where the money was short (Cash, UPI or Card).');
    const short = round2_(total - received);
    if (short > n_(full[mode.toLowerCase()]) + 0.009) throw new Error('Only ₹' + n_(full[mode.toLowerCase()]) + ' of this bill was paid by ' + mode + '.');
    const x = shRows_();
    x.rows.forEach((q, i) => { if (s_(q[0]) === s_(d.no) && s_(q[12]) === 'Active') x.sh.getRange(i + 2, 13).setValue('Replaced'); });
    const now = new Date();
    x.sh.getRange(x.sh.getLastRow() + 1, 1, 1, SH_H.length).setValues([[s_(d.no), ymd_(r[BC['Date']]), s_(r[BC['Location']]), s_(r[BC['Event / venue']]).split('\n')[0],
      total, received, short, mode, reason, txt_(d.note, 200), user ? user.name : 'Owner', now, 'Active']]);
    applyShortToBill_(row, r, b, { short: short, received: received, mode: mode, reason: reason, note: txt_(d.note, 200), by: user ? user.name : 'Owner', at: now.toISOString() });
  } finally { lock.releaseLock(); }
  return { bill: getBillByNo_(d.no) };
}
/** Balance received later, or recorded by mistake: the bill counts as fully paid again. */
function clearShort_(d, user) {
  const lock = LockService.getScriptLock(); lock.waitLock(30000);
  try {
    const row = findBillRow_(d.no); if (row < 0) throw new Error('Bill not found.');
    const r = btab_('bills').getRange(row, 1, 1, BH.bills.length).getValues()[0];
    shortGuard_(r, user, false);
    const x = shRows_(); let n = 0;
    const st = d.recovered ? 'Balance received ' + ymd_(new Date()) + ' (' + (user ? user.name : 'Owner') + ')' : 'Removed (' + (user ? user.name : 'Owner') + ')';
    x.rows.forEach((q, i) => { if (s_(q[0]) === s_(d.no) && s_(q[12]) === 'Active') { x.sh.getRange(i + 2, 13).setValue(st); n++; } });
    if (!n) throw new Error('No short payment on this bill.');
    applyShortToBill_(row, r, JSON.parse(s_(r[BC['Bill data']])), null);
  } finally { lock.releaseLock(); }
  return { bill: getBillByNo_(d.no) };
}

